INSERT INTO manufacturers (id, name, country, SMALLINT, notes, link) VALUES
(1, 'Specialized', 'USA', 1974, 'Specialized is a brand of bicycles that was founded by Mike Sinyard in 1974. Sinyard started the company out of his home in Northern California, and it has since grown into one of the leading bicycle brands in the world. Specialized is known for its high-quality and innovative products, and it offers a wide range of bicycles for different types of riding, including road, mountain, and hybrid bikes. The company is headquartered in Morgan Hill, California, and it has operations and facilities around the world.', 'https://www.specialized.com/'),
(2, 'Giant', 'Taiwan', 1972, 'Giant is a Taiwanese brand of bicycles that was founded by King Liu in 1972. Liu started the company with a small team of like-minded individuals who shared a passion for cycling and a vision for creating the finest bikes in the world. Over the years, Giant has grown into one of the largest and most respected bicycle brands in the world, and it is known for its high-quality and innovative bikes. The company is headquartered in Taichung, Taiwan, and it has a global presence, with a network of distributors, retailers, and service centers around the world. King Liu is now retired, but his legacy lives on through the company he founded, which continues to be a leader in the cycling industry.', 'https://www.giant-bicycles.com/'),
(3, 'Cannondale', 'USA', 1971, 'Cannondale is a brand of bicycles that was founded by Joe Montgomery and Jim Catrambone in 1971. The company is headquartered in Bethel, Connecticut, and it is known for its high-quality and innovative bikes. Cannondale has a reputation for producing some of the finest bicycles on the market, and it is known for its commitment to innovation and sustainability. The company offers a wide range of bikes for different types of riding, including road, mountain, and hybrid bikes. In addition to bikes, Cannondale also produces a range of cycling apparel, accessories, and parts.', 'https://www.cannondale.com/'),
(4, 'Trek', 'USA', 1975, 'In December, 1975, Dick Burke and Bevil Hogg established Trek Bicycle', 'https://www.trekbikes.com/'),
(5, 'Merida', 'Taiwan', 1972, 'Founded in 1972 by Ike Tseng', 'https://www.merida-bikes.com/'),
(6, 'De Rosa', 'Italy', 1958, 'Company founder Ugo De Rosa was born on January 27, 1934 in Milan, Italy', 'https://derosa.it/'),
(7, 'Vitus', 'Northern Ireland', 2009, 'In 2009 a team of bike engineers in Northern Ireland were working on developing a brand-new range of bikes and discovered the Vitus brand was for sale. The name was first used in 1930 in France', 'https://vitusbikes.com/'),
(8, 'Canyon', 'Germany', 1985, 'Canyon is a German brand of bicycles that is known for its high-quality and innovative bikes. The company was founded in 1985 by Roman Arnold and has since grown into one of the leading bicycle brands in the world. Canyon produces a wide range of bikes for different types of riding, including road, mountain, hybrid, and electric bikes. The company is known for its commitment to performance and value, and it uses advanced materials and technology to create bikes that are both high-performing and affordable. Canyon has a global presence, with a network of distributors, retailers, and service centers around the world.', 'https://www.canyon.com/'),
(9, 'Swift Carbon', 'South Africa / UK', 2008, 'Founded by South African Mark Blewett', 'https://swiftcarbon.com/'),
(10, 'Scott', 'USA', 1958, 'REVOLUTION OF SKI POLES : BIRTH OF SCOTT', 'https://www.scott-sports.com/'),
(11, 'Ribble', 'British', 1897, 'Drawing inspiration from the river which flows through the heart of Preston, the choice of the name ‘Ribble’ was an obvious one.', 'https://www.ribblecycles.co.uk/'),
(12, 'Orbea', 'Spain', 1840, 'Orbea was founded in 1840 by brothers Juan Manuel, Mateo, and Casimiro Orbea in Eibar, Basque Country, Spain. Originally a rifle and gun producer, Orbea exited the gun business and began designing and producing bicycles as Orbea Bicycles in 1930.', 'https://www.orbea.com/'),
(13, 'Santa Cruz', 'USA', 1993, 'Santa Cruz Bicycles was founded by Rob Roskopp, Mike Marquez and Rich Novak in 1993', 'https://www.santacruzbicycles.com/'),
(14, 'Nukeproof', 'USA', 1990, 'founder John Muenzenmeyer. 2004 Michael Cowan, Northern Irish downhill racer, saw the chance to save the brand.', 'https://nukeproof.com/'),
(15, 'Commencal', 'Andorra', 2000, 'Max COMMENCAL, first company SUNN', 'https://www.commencal-store.co.uk/'),
(16, 'Pinarello', 'Italy', 1953, 'Giovanni Pinarello', 'https://pinarello.com/'),
(17, 'Focus', 'Germany', 1992, 'Headed up by cyclocross World Champion Mike Kluge.', 'https://www.focus-bikes.com/'),
(18, 'Cervelo', 'Canada', 1995, 'Founded in 1995 by Phil White and Gérard Vroomen', 'https://www.cervelo.com/'),
(19, 'BMC', 'Switzerland', 1986, 'Bob Bigelow founded BMC. Andy Rihs took over BMC in 2000', 'https://www.bmc-switzerland.com/'),
(20, 'Wilier', 'Italy', 1906, 'Wilier Triestina - founded in 1906 by Pietro Dal Molin in Bassano del Grappa', 'https://wilier.com/'),
(21, 'Argon 18', 'Canada', 1989, '', 'https://www.argon18.com/'),
(23, 'Colnago', 'Italy', 1954, 'Founded by Ernesto Colnago', 'https://www.colnago.com/'),
(24, 'Fuji', 'Japan', 1899, 'The company is a descendant of Nichibei Fuji Cycle Company, Ltd. a bicycle manufacturer originally established in Japan in 1899', 'https://www.fujibikes.com/'),
(25, 'Factor', 'UK', 2007, 'founder John Bailey', 'https://factorbikes.com/'),
(26, 'Bianchi', 'Italy', 1885, 'Bianchi is the worlds oldest bicycle manufacturing company in existence, founded by Edoardo Bianchi', 'https://www.bianchi.com/'),
(27, 'Cube', 'Germany', 1993, ' founded 1993 by Marcus Pürner', 'https://www.cube.eu/'),
(28, 'Radon', 'Germany', 1992, 'Owned by the German bike shop powerhouse Bike-Discount Radon bikes was founded in 1992 with the goal of supplying top quality bikes at affordable prices', 'https://www.radon-bikes.de/'),
(29, 'Basso', 'Italy', 1977, 'Founded in 1977 by Alcide Basso brother of Marino Basso', 'https://bassobikes.com/'),
(30, 'Look', 'France', 1951, 'Founder Jean Beyl - started making ski bindings', 'https://www.lookcycle.com/'),
(31, 'KTM', 'Austria', 1934, 'Kraftfahrzeug Trunkenpolz Mattighofen - It was formed in 1992 but traces its foundation to as early as 1934 - mainly makes motorcycles ', 'https://www.ktm-bikes.at/'),
(32, 'Ceepo', 'Japan', 2003, 'CEEPO was founded by Nobuyuki Joe Tanaka in Aichi Japan 2003', 'https://www.ceepobike.com/'),
(33, 'Gusto', 'Taiwan', 2011, 'GUSTO was established in Taiwan in 2011', 'https://www.gustobike.com/'),
(34, 'Polygon', 'Indonesia', 1989, 'Polygon Bikes is a bicycles trade name made by PT Insera Sena an Indonesian bicycle manufacturer based in Sidoarjo East Java.', 'https://www.polygonbikes.com/'),
