(77, 'Kona', 'Canada / USA', 1988, 'KONA was founded in 1988 by Dan Gerhard and Jacob Heilbron in Vancouver, BC', 'https://konaworld.com/'),
(78, 'YT Industries', 'Germany', 2007, 'YT Industries is a direct-sales mountain bike brand based in Forcheim, Germany, run by Markus Flossmann. It was founded in 2007', 'https://www.yt-industries.com/'),
(79, 'Orange', 'UK', 1988, 'Orange bikes is based in Halifax, UK', 'https://www.orangebikes.com/'),
